import CrudPage from '../../components/ui/CrudPage';
import { designationApi } from '../../api/services';
import { Input } from '../../components/ui';

const columns = [
  { key: 'name', label: 'Name' },
  { key: 'code', label: 'Code' },
  { key: 'level', label: 'Level' },
];

function FormFields({ register, errors }) {
  return (
    <>
      <Input label="Name" error={errors.name?.message} {...register('name', { required: 'Required' })} />
      <Input label="Code" error={errors.code?.message} {...register('code', { required: 'Required' })} />
      <Input label="Level" type="number" {...register('level')} />
      <Input label="Description" {...register('description')} />
    </>
  );
}

export default function DesignationsPage() {
  return (
    <CrudPage
      queryKey="designations"
      api={designationApi}
      columns={columns}
      FormFields={FormFields}
      entityName="Designation"
    />
  );
}
